function lab(){let c=labs[state.lab];$('#main').innerHTML=hero('THE NUMERICAL WORKBENCH','বুঝে করি, ধাপে ধাপে।', 'বইয়ের worked examples + নিজের সংখ্যা দিয়ে practice। প্রতিটি হিসাবের formula, substitution ও result দেখুন।',`16 interactive tools · ${E.length} guided examples · Every step explained`)+`<div class="labgrid" style="margin-top:25px"><aside class="labmenu">${Object.entries(labs).map(([k,v])=>`<button data-lab="${k}" class="${k===state.lab?'active':''}">${esc(v.name)}</button>`).join('')}</aside><div><section class="card"><span class="pill">INTERACTIVE SOLVER</span><h2>${esc(c.name)}</h2><p class="bn">${esc(c.desc)}</p><form id="labform"><div class="formgrid">${c.fields.map(([id,label,val,type])=>`<div class="field"><label for="f-${id}">${esc(label)}</label>${Array.isArray(type)?`<select id="f-${id}">${type.map(t=>`<option ${t===val?'selected':''}>${esc(t)}</option>`).join('')}</select>`:`<input id="f-${id}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(val)}" required>`}</div>`).join('')}</div><button class="primary">Calculate & explain →</button></form><div id="labresult" aria-live="polite"></div></section><details class="card example-library"><summary style="cursor:pointer;font-weight:700;font-size:14px">${E.length} guided examples · book problems + extra practice</summary><label class="example-search-label">Find a worked example<input id="example-search" type="search" placeholder="Search: CRC, VLSM, delay, PCM…"></label><p id="example-count" class="small" role="status">${E.length} examples</p>${E.map(exampleHTML).join('')}</details></div></div>`;$$('[data-lab]').forEach(b=>b.onclick=()=>{state.lab=b.dataset.lab;lab()});$('#labform').onsubmit=e=>{e.preventDefault();calculate()};bindExamples();$('#example-search').oninput=e=>{let q=e.target.value.trim().toLowerCase(),n=0;$$('.example-library > .tutorial').forEach((root,i)=>{let match=(E[i].title+' '+tutorials[i].map(s=>s.title+' '+s.why+' '+s.math).join(' ')).toLowerCase().includes(q);root.classList.toggle('hidden',!match);if(match)n++});$('#example-count').textContent=n+' / '+E.length+' examples'+(n?'':' — অন্য term দিয়ে খুঁজুন।')};calculate()}
const table=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function calculate(){try{let values=Object.fromEntries(labs[state.lab].fields.map(([id])=>[id,$('#f-'+id).value]));let solved=solveMath(state.lab,values);$('#labresult').innerHTML=`<div class="result"><h3>সমাধান • কেন, কীভাবে, কত</h3><p class="small">প্রতি ধাপে কারণ → হিসাব → যাচাই। আরও সহজ ব্যাখ্যা খুলে দেখুন।</p>${solverStepsHTML(solved.steps)}${solved.result.length?`<details class="result-summary"><summary>সারাংশ ও final answer দেখুন →</summary>${table(['Quantity','Result'],solved.result.map(([a,b])=>[esc(a),esc(b)]))}</details>`:''}${solved.visual}${directVideo(labs[state.lab].name)}${videoLinks(labs[state.lab].name)}</div>`;bindSolverSteps($('#labresult'))}catch(e){$('#labresult').innerHTML=`<p class="error" role="alert">${esc(e.message)}</p>`}}
const diagramNames={osi:'OSI stack',topology:'Network topologies',duplex:'Duplex modes',signal:'Signals & line codes',encap:'Encapsulation',mux:'Multiplexing',tcp:'TCP handshake',dhcp:'DHCP • DORA',dns:'DNS resolution'};
function node(x,y,w,h,text,hot=false){return`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" class="${hot?'highlight':'node'}"/><text x="${x+w/2}" y="${y+h/2+5}" text-anchor="middle">${esc(text)}</text>`}
function line(x,y,a,b,hot=false,arrow=true){return`<path d="M${x} ${y}L${a} ${b}" class="${hot?'hotedge':'edge'}" ${arrow?'marker-end="url(#arr)"':''}/>`}
function svgWrap(c){return`<svg viewBox="0 0 620 330" role="img" aria-label="Interactive educational network diagram"><defs><marker id="arr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#73956a"/></marker></defs>${c}</svg>`}
function diagramSVG(type,n=0){let c='',note='',max=3;
if(type==='osi'){const names=['7 Application · user services','6 Presentation · format / encryption','5 Session · dialogue / checkpoints','4 Transport · ports / TCP / UDP','3 Network · IP / routing','2 Data Link · frame / MAC','1 Physical · raw bits'];max=7;n%=max;names.forEach((t,i)=>{c+=node(110,5+i*45,400,37,t,i===n)});note=['Application:HTTP,DNS,FTP networkservices দেয়।','Presentation:translation,compression,encryption conceptual functions।','Session:establish,manage,terminate dialogue।','Transport:process-to-process,port,TCP/UDP।','Network:IPaddress,packet,routing।','DataLink:MAC,frame,switch,error detection।','Physical:bit,voltage,cable,hub/repeater।'][n]}
if(type==='topology'){max=4;n%=max;let pts=[[90,75],[310,45],[530,75],[530,245],[310,285],[90,245]];if(n===0){pts.forEach((p,i)=>pts.forEach((q,j)=>{if(j>i)c+=line(...p,...q,false,false)}));note='Full mesh: 6 devices → 6×5/2 = 15 links। প্রতি device-এ 5 ports।'}if(n===1){pts.forEach(p=>c+=line(310,165,...p,true,false));c+=node(260,143,100,42,'Switch',true);note='Star: সব device কেন্দ্রের switch-এ যুক্ত। কেন্দ্রের switch নষ্ট হলে সবাই বিচ্ছিন্ন।'}if(n===2){c+=line(55,165,570,165,true,false);pts=[[100,75],[240,245],[380,75],[520,245]];pts.forEach(p=>c+=line(p[0],p[1],p[0],165,false,false));note='Bus: একটি backbone cable; দুই প্রান্তে terminator। Backbone ছিঁড়লে পুরো network বন্ধ হতে পারে।'}if(n===3){pts.forEach((p,i)=>c+=line(...p,...pts[(i+1)%pts.length],true));note='Ring: প্রতিটি device-এর দুই neighbour। Token পেলে পাঠায়, তাই সংঘর্ষ এড়ানো যায়।'}pts.forEach((p,i)=>c+=node(p[0]-27,p[1]-18,54,36,String.fromCharCode(65+i)));}
if(type==='duplex'){max=3;n%=max;c+=node(40,115,150,65,'Station A',true)+node(430,115,150,65,'Station B');if(n===0){c+=line(200,147,420,147,true);note='Simplex: শুধু A → B। যেমন TV broadcast।'}if(n===1){c+=line(200,130,420,130,true)+line(420,170,200,170);c+='<text x="310" y="230" text-anchor="middle">One direction at a time</text>';note='Half-duplex: দুইদিকে যায়, কিন্তু পালা করে। যেমন walkie-talkie।'}if(n===2){c+=line(200,130,420,130,true)+line(420,170,200,170,true);c+='<text x="310" y="230" text-anchor="middle">Both directions simultaneously</text>';note='Full-duplex: একই সময়ে দুইদিকে যায়। যেমন phone call বা switched Ethernet।'}}
if(type==='signal'){max=4;n%=max;let bits='1011001';for(let i=0;i<8;i++)c+=`<path d="M${65+i*70} 60V275" stroke="#d5dfcf" stroke-dasharray="3 5"/>`;for(let i=0;i<7;i++)c+=`<text x="${100+i*70}" y="40" text-anchor="middle">${bits[i]}</text>`;let pts=[],level=0,last=-1;for(let i=0;i<7;i++){let b=+bits[i],x=65+i*70;if(n===0){let y=b?215:115;pts.push([x,y],[x+70,y])}if(n===1){if(b)level=1-level;let y=level?115:215;pts.push([x,y],[x+70,y])}if(n===2){let y=b?215:115,z=b?115:215;pts.push([x,y],[x+35,y],[x+35,z],[x+70,z])}if(n===3){let y=165;if(b){last=-last;y=165-last*50}pts.push([x,y],[x+70,y])}}c+=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#397b4e" stroke-width="4"/>`;c+=`<text x="310" y="315" text-anchor="middle">${['NRZ-L: 1 = negative, 0 = positive','NRZ-I: transition at start for 1','Manchester IEEE: 1 low to high','AMI: alternate polarity for each 1'][n]}</text>`;note=['NRZ-L-এlevelbitবোঝায়;এখানে1negative।','NRZ-I-তেinitiallevelনির্দিষ্টকরতে হয়;1এstarttransition।','Manchester-এমাঝেtransitionঅবশ্যই;IEEEconventionএ1low→high।','AMI:0zero;1পালাকরেpositive/negative;দীর্ঘ0এclockingসমস্যা।'][n]}
if(type==='encap'){max=5;n%=max;let names=['Application data','TCP header + Data','IP header + TCP segment','Ethernet header + IP packet + FCS','Physical: 010101…'];for(let i=0;i<5;i++){c+=node(45+i*13,20+i*59,530-i*26,43,names[i],i===n);if(i<4)c+=line(310,64+i*59,310,78+i*59)}note=['Applicationdataশুরুতেpayload।','Transportsegmentheaderএportsওsequenceinformation।','NetworkpacketIPheaderএsource/destination।','EthernetframeএMACheaderওCRC/FCStrailer।','Physicalmediumএbits signalহিসেবেচলে;receiverউল্টোকরেdecapsulate।'][n]}
if(type==='mux'){max=3;n%=max;for(let i=0;i<3;i++){c+=node(15,40+i*95,90,40,'User '+(i+1),i===n)+line(105,60+i*95,200,165,i===n)+line(420,165,515,60+i*95,i===n)+node(515,40+i*95,90,40,'User '+(i+1),i===n)}c+=node(180,135,75,60,'MUX',true)+node(365,135,75,60,'DEMUX',true)+line(255,165,365,165,true);c+='<text x="310" y="115" text-anchor="middle">Shared link</text>';note=['FDM:আলাদাফ্রিকোয়েন্সিতেএকইসময়;guardbands।','TDM:একইlinkপালাকরেতাইমslotএ;statisticalTDMশুধুঅ্যাকটিভuserকেslotদেয়।','WDM:একfibreএআলাদাcolour/wavelength।'][n]}
if(['tcp','dhcp'].includes(type)){let msgs=type==='tcp'?['1 SYN (seq=x)','2 SYN + ACK (seq=y, ack=x+1)','3 ACK (ack=y+1)']:['1 Discover · client looks for server','2 Offer · server offers an IP','3 Request · client selects offer','4 ACK · lease confirmed'];max=msgs.length;n%=max;c+=node(40,10,130,40,'Client',true)+node(450,10,130,40,'Server');c+='<path d="M105 55V325M515 55V325" stroke="#b4c5ac" stroke-dasharray="4 5"/>';msgs.forEach((t,i)=>{let y=95+i*67,reverse=i%2===1;c+=line(reverse?505:115,y,reverse?115:505,y,i===n);c+=`<text x="310" y="${y-12}" text-anchor="middle">${esc(t)}</text>`});note=type==='tcp'?['Client SYN পাঠায়, initial sequence number x দিয়ে শুরু করে।','Server নিজের sequence y পাঠায় এবং x+1 দিয়ে client-এর SYN acknowledge করে।','Client y+1 acknowledge করলে connection established হয়।'][n]:['Client broadcast করে DHCP server খোঁজে।','Server available IP ও configuration offer করে।','Client একটি offer বেছে request পাঠায়, অন্য server-ও তা জানতে পারে।','Server ACK দিয়ে lease ও configuration confirm করে।'][n]}
if(type==='dns'){max=5;n%=max;let labels=['Client','Resolver','Root','TLD','Authoritative'],pts=[[30,55],[235,55],[440,55],[440,220],[235,220]];pts.forEach((p,i)=>{c+=node(...p,140,50,labels[i],i===n);if(i<4)c+=line(p[0]+70,p[1]+50,pts[i+1][0]+70,pts[i+1][1],i===n)});c+='<text x="110" y="260" text-anchor="middle">Cache / TTL</text>';note=['Client-এর cache-এ answer না থাকলে configured resolver-কে query দেয়।','Recursive resolver বাকি server-গুলোকে query করে।','Root server TLD name server-এর referral দেয়।','TLD authoritative name server-এর referral দেয়।','Authoritative server answer দেয়। Resolver TTL অনুযায়ী cache করে client-কে answer দেয়।'][n]}
return{html:svgWrap(c),note,max}}
function pageDiagram(p){let type=p<=8&&p>=5?'duplex':p>=9&&p<=14?'signal':p>=15&&p<=18?'signal':p>=19&&p<=22?'mux':p>=23&&p<=26?'topology':p>=27&&p<=29?'osi':p===52?'tcp':p>=53&&p<=54?'dhcp':null;if(!type)return'';let d=diagramSVG(type,0);return`<div class="divider">VISUAL MEMORY</div><div class="diagram">${d.html}</div><p class="small">${esc(d.note)}</p><button class="diagramjump" data-targetdiagram="${type}">Explore interactive diagrams →</button>`}
function diagrams(){let d=diagramSVG(state.diagram,state.dstep);$('#main').innerHTML=hero('SEE HOW IT WORKS','Diagram দেখে মনে রাখি।','Click through each layer, step or network arrangement. পরে না দেখে খাতায় এঁকে ফেলুন।','9 visual topics · Click to explore · Draw from memory')+`<div class="chips">${Object.entries(diagramNames).map(([k,n])=>`<button data-diagram="${k}" class="${state.diagram===k?'active':''}">${n}</button>`).join('')}</div><div class="card"><div class="quizhead"><h2>${diagramNames[state.diagram]}</h2><span class="badge">Step ${state.dstep%d.max+1} / ${d.max}</span></div><div class="diagram">${d.html}</div><div class="notice bn">${esc(d.note)}</div><div class="toolbar"><button id="dprev">← Previous</button><button class="primary" id="dnext">Next step →</button></div></div>`;$$('[data-diagram]').forEach(b=>b.onclick=()=>{state.diagram=b.dataset.diagram;state.dstep=0;diagrams()});$('#dprev').onclick=()=>{state.dstep=(state.dstep-1+d.max)%d.max;diagrams()};$('#dnext').onclick=()=>{state.dstep=(state.dstep+1)%d.max;diagrams()}}
function practice(){let q=Q[state.qindex],selected=state.answers[q.id],canReveal=!state.mock||state.submitted,answered=Object.keys(state.answers).length,score=Q.filter(x=>state.answers[x.id]===x.answer).length;$('#main').innerHTML=hero('TEST YOUR UNDERSTANDING','প্রস্তুতি যাচাই, এক প্রশ্নে এক ধাপ।','বইয়ের সব ৬০টি MCQ, উত্তর ও সহজ explanation। Practice-এ সঙ্গে সঙ্গে feedback; mock-এ submit-এর পরে।','60 book questions · 45-minute mock · No negative marking')+`<div class="toolbar"><div class="chips" style="margin:0"><button id="practice-mode" class="${!state.mock?'primary':''}">Practice mode</button><button id="mock-start" class="${state.mock?'primary':''}">${state.mock&&!state.submitted?'Restart':'Start'} 45-min mock</button></div>${state.mock?'<span id="timer" class="timer"></span>':`<span class="small">${answered}/60 answered · ${score} correct</span>`}</div>${state.submitted?`<div class="stats"><div class="card"><div class="small">YOUR SCORE</div><div class="statnum">${score} / 60</div></div><div class="card"><div class="small">ACCURACY (ALL 60)</div><div class="statnum">${Math.round(score/60*100)}%</div></div><div class="card"><div class="small">UNANSWERED</div><div class="statnum">${60-answered}</div></div></div>`:''}<section class="card"><div class="quizhead"><span class="pill">QUESTION ${q.id} OF 60</span><span class="badge">${state.mock?'MOCK TEST':'PRACTICE'}</span></div><h2 style="margin-top:22px">${esc(q.q)}</h2><div class="quizoptions">${q.opts.map((o,i)=>`<button class="option ${selected===i?'selected':''} ${canReveal&&selected!==undefined?(q.answer===i?'correct':selected===i?'wrong':''):''}" data-option="${i}" ${state.submitted?'disabled':''}><span>${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div>${canReveal&&selected!==undefined?`<div class="notice bn"><b>${selected===q.answer?'✓ সঠিক!':'↻ আবার বুঝে নিন।'} Answer: ${'ABCD'[q.answer]}</b><br>${esc(q.why)}<br><button id="review-page" style="margin-top:10px">Review PDF page ${q.page} →</button></div>`:''}<div class="toolbar"><button id="qprev" ${state.qindex===0?'disabled':''}>← Previous</button><button id="qnext" class="primary" ${state.qindex===59?'disabled':''}>Next question →</button></div></section><section class="card"><div class="quizhead"><h3>Question navigator</h3>${state.mock&&!state.submitted?'<button id="mock-submit" class="primary">Submit mock →</button>':!state.mock?'<button id="resetpractice">Reset practice</button>':''}</div><p class="small">Filled squares = answered. Skip করে পরে ফিরে আসতে পারেন।</p><div class="questiongrid">${Q.map((x,i)=>`<button data-q="${i}" class="${i===state.qindex?'active':''} ${state.answers[x.id]!==undefined?'answered':''}" aria-label="Question ${x.id}${state.answers[x.id]!==undefined?', answered':''}">${x.id}</button>`).join('')}</div></section>${state.submitted?`<section class="card"><h3>Review missed questions</h3><div class="chips">${Q.filter(x=>state.answers[x.id]!==x.answer).map(x=>`<button data-missed="${x.id-1}">Q${x.id}</button>`).join('')||'<p>সব উত্তর সঠিক। এবার written questions practice করুন।</p>'}</div></section>`:''}`;
$$('[data-option]').forEach(b=>b.onclick=()=>{state.answers[q.id]=+b.dataset.option;save(state.mock?'mockanswers':'answers',state.answers);practice()});$$('[data-q]').forEach(b=>b.onclick=()=>{state.qindex=+b.dataset.q;practice()});$$('[data-missed]').forEach(b=>b.onclick=()=>{state.qindex=+b.dataset.missed;practice();window.scrollTo({top:200,behavior:'smooth'})});$('#qprev').onclick=()=>{state.qindex--;practice()};$('#qnext').onclick=()=>{state.qindex++;practice()};$('#review-page')?.addEventListener('click',()=>go(q.page));$('#mock-start').onclick=()=>{state.mock=true;state.submitted=false;state.answers={};state.qindex=0;state.deadline=Date.now()+45*60*1000;save('deadline',state.deadline);save('mockanswers',{});practice()};$('#practice-mode').onclick=()=>{state.mock=false;state.submitted=false;state.deadline=null;save('deadline',null);state.answers=read('answers',{});practice()};$('#mock-submit')?.addEventListener('click',submitMock);$('#resetpractice')?.addEventListener('click',()=>{state.answers={};save('answers',{});state.qindex=0;practice()});updateTimer()}
function submitMock(){state.submitted=true;save('deadline',null);state.deadline=null;practice();toast('Mock submitted. Score ও missed questions দেখুন।')}
function updateTimer(){if(!state.mock||state.submitted)return;let remain=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=String(Math.floor(remain/60)).padStart(2,'0')+':'+String(remain%60).padStart(2,'0');if(remain===0){if(state.view==='practice')submitMock();else{state.submitted=true;save('deadline',null);state.deadline=null}}}setInterval(updateTimer,1000);
const formulas=[['Frequency','f = 1 / T','T seconds → Hz'],['Period','T = 1 / f','f Hz → seconds'],['Bits per symbol','b = log₂ L','L signal levels'],['Bit rate','R = baud × log₂ L','bps'],['Baud','S = R / log₂ L','symbols/s'],['Nyquist capacity','C = 2B log₂ L','B Hz; noiseless'],['Shannon capacity','C = B log₂(1 + SNR)','SNR ratio, not dB'],['Power gain','G = 10 log₁₀(Pout / Pin)','dB; loss negative'],['SNR','SNR = Ps / Pn','ratio'],['SNR in dB','SNRdB = 10 log₁₀ SNR','ratio = 10^(dB/10)'],['Sampling','fs ≥ 2 fmax','samples/s'],['PCM rate','R = fs × bits × channels','bps'],['Propagation','Tprop = distance / speed','m ÷ m/s'],['Transmission','Ttx = bits / rate','bits ÷ bps'],['BDP','BDP = bandwidth × delay','bits; specify one-way/RTT'],['Mesh links / pairwise keys','n(n−1) / 2','n devices/users'],['Ports per mesh device','n − 1','total endpoints = n(n−1)'],['Number of subnets','2ˢ','s borrowed bits'],['Ordinary usable hosts','2ʰ − 2','h=32−prefix; /31,/32 exceptions'],['Subnet increment','256 − partial mask octet','use correct octet'],['Hamming parity bits','2ʳ ≥ m + r + 1','smallest integer r'],['Asymmetric total keys','2n','n public + n private'],['Go-Back-N window','W ≤ 2ᵐ − 1','m sequence bits'],['Selective Repeat window','W ≤ 2^(m−1)','equal sender/receiver windows']];
