function written(){$('#main').innerHTML=hero('WRITE FOR METHOD MARKS','উত্তর সাজাই, marks বাড়াই।','বইয়ের ২৪টি written question-এর answer framework, model opening ও পূর্ণ topic notes। Numericals-এর প্রতিটি ধাপ Math lab-এ দেখুন।','24 written questions · Model openings · Linked solutions')+`<section class="card" style="margin-top:24px"><h2>পরীক্ষার খাতায় উত্তর দেওয়ার পদ্ধতি</h2><div class="memory bn">Definition → organised points/table → diagram → example বা calculation। প্রশ্নের marks অনুযায়ী depth দিন। Math-এ unit ও working লিখুন।</div></section><section class="card written">${W.map(([q,pages,opening,plan],i)=>`<details><summary>Q${i+1}. ${esc(q)}</summary><span class="pill">MODEL OPENING</span><p>${esc(opening)}</p><div class="notice bn"><b>যেভাবে সাজাবেন:</b> ${esc(plan)}</div><div class="divider">MODEL ANSWER CONTENT • বাংলা + English</div>${pages.map(p=>`<details class="example"><summary>Page ${p} · ${esc(L[p-1].title)}</summary><div style="padding:17px">${explain(L[p-1].bn)}<button class="writtenpage" data-wpage="${p}">Open complete page & diagrams →</button></div></details>`).join('')}${E.filter(e=>pages.includes(e.page)).map(exampleHTML).join('')}<label class="small" for="answer-${i}">নিজের উত্তর লিখুন • saved on this browser</label><textarea class="notes writtennote" id="answer-${i}" data-answer="${i}" placeholder="Write your timed answer here…">${esc(read('written-'+i,''))}</textarea><p class="small">Checklist: definition ✓ explanation ✓ comparison/diagram ✓ example/working ✓</p></details>`).join('')}</section>`;$$('[data-wpage]').forEach(b=>b.onclick=()=>go(+b.dataset.wpage));$$('.writtennote').forEach(n=>n.oninput=()=>save('written-'+n.dataset.answer,n.value));bindExamples()}
